    explicit ImageRenderState(IDirect3DDevice9* d):device(d){for(size_t i=0;i<render.size();++i)device->GetRenderState(renderKeys[i],&render[i]);for(size_t i=0;i<stage.size();++i)device->GetTextureStageState(0,stageKeys[i],&stage[i]);for(size_t i=0;i<sampler.size();++i)device->GetSamplerState(0,samplerKeys[i],&sampler[i]);device->GetTextureStageState(1,D3DTSS_COLOROP,&fog[0]);device->GetTextureStageState(1,D3DTSS_ALPHAOP,&fog[1]);device->GetTransform(D3DTS_WORLD,&transforms[0]);device->GetTransform(D3DTS_VIEW,&transforms[1]);device->GetTransform(D3DTS_PROJECTION,&transforms[2]);device->GetTexture(0,texture.GetAddressOf());device->GetFVF(&fvf);device->GetVertexDeclaration(declaration.GetAddressOf());device->GetVertexShader(shader.GetAddressOf());device->GetPixelShader(pixelShader.GetAddressOf());device->GetStreamSource(0,stream.GetAddressOf(),&offset,&stride);}
